using AfriWallet.Compliance.Readiness.Models;
namespace AfriWallet.Compliance.Readiness.Checks;
public sealed class AuditCapabilityCheck:IComplianceReadinessCheck { public string Code=>"CMP-RDY-006";public Task<ReadinessCheck> ExecuteAsync(string root,CancellationToken ct=default){ct.ThrowIfCancellationRequested();string[] files=[RepositoryCheckUtilities.Resolve(root,"backend","src","Compliance","RiskScoring.Application","Abstractions","IRiskAuditStore.cs"),RepositoryCheckUtilities.Resolve(root,"backend","src","Compliance","CaseManagement.Application","Abstractions","IComplianceCaseAuditStore.cs")];var missing=files.Where(x=>!File.Exists(x)).Select(Path.GetFileName).ToArray();return Task.FromResult(new ReadinessCheck(Code,"Compliance audit capability",missing.Length==0?ReadinessStatus.Passed:ReadinessStatus.Failed,missing.Length==0?"Risk and case audit abstractions present":$"Missing: {string.Join(", ",missing)}"));} }